import{_ as e,o as d,c as a,a3 as o}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"MiniTavern에서 이미지 설정","description":"설정 → 이미지 생성 → 이미지 연결 — 로컬 A1111 / ComfyUI 또는 클라우드 이미지 API.","frontmatter":{"title":"MiniTavern에서 이미지 설정","description":"설정 → 이미지 생성 → 이미지 연결 — 로컬 A1111 / ComfyUI 또는 클라우드 이미지 API.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"MiniTavern에서 이미지 설정 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"설정 → 이미지 생성 → 이미지 연결 — 로컬 A1111 / ComfyUI 또는 클라우드 이미지 API."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/local/image-gen/connect-app"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/local/image-gen/connect-app"}]]},"headers":[],"relativePath":"ko/local/image-gen/connect-app.md","filePath":"ko/local/image-gen/connect-app.md","lastUpdated":1787224147000}'),r={name:"ko/local/image-gen/connect-app.md"};function n(i,t,l,c,s,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="minitavern에서-이미지-설정" tabindex="-1">MiniTavern에서 이미지 설정 <a class="header-anchor" href="#minitavern에서-이미지-설정" aria-label="Permalink to &quot;MiniTavern에서 이미지 설정&quot;">​</a></h1><p>App 경로: <strong>설정 → 이미지 생성 → 이미지 연결</strong>.</p><p>파라미터, 응답 이미지, 키워드 트리거: <a href="/ultra_guides/ko/manual/model-link#이미지-생성연결--응답-이미지--키워드">모델 연결 · 이미지</a>.</p><h2 id="이미지-연결-새로-만들기" tabindex="-1">이미지 연결 새로 만들기 <a class="header-anchor" href="#이미지-연결-새로-만들기" aria-label="Permalink to &quot;이미지 연결 새로 만들기&quot;">​</a></h2><ol><li>MiniTavern → 하단 <strong>설정</strong>.</li><li><strong>이미지 생성</strong> → <strong>이미지 연결</strong>.</li><li><strong>새로 만들기</strong>.</li><li><strong>플랫폼</strong> 선택, Base URL / API Key / 모델（플랫폼별）.</li><li><strong>테스트</strong> 성공 후 저장, 기본값（목록 지원 시）.</li></ol><h2 id="로컬-a1111" tabindex="-1">로컬 A1111 <a class="header-anchor" href="#로컬-a1111" aria-label="Permalink to &quot;로컬 A1111&quot;">​</a></h2><p>먼저 <a href="./a1111">A1111 설치 + <code>--api --listen</code></a>.</p><table tabindex="0"><thead><tr><th>항목</th><th>예</th></tr></thead><tbody><tr><td>플랫폼</td><td><strong>A1111(SD WebUI)</strong>（또는 Custom A1111）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:7860</code></td></tr><tr><td>API Key</td><td>보통 비움; WebUI <code>--api-auth</code> 시 안내에 따라</td></tr><tr><td>모델</td><td>비움 또는 WebUI checkpoint 이름（App 목록）</td></tr></tbody></table><p><code>YOUR_PC_IP</code>는 PC LAN IP.<br><strong><code>http://127.0.0.1:7860</code> 금지</strong>（PC 자신, 폰 아님）.</p><h2 id="로컬-comfyui" tabindex="-1">로컬 ComfyUI <a class="header-anchor" href="#로컬-comfyui" aria-label="Permalink to &quot;로컬 ComfyUI&quot;">​</a></h2><p>먼저 <a href="./comfyui">ComfyUI + <code>--listen</code></a>.</p><table tabindex="0"><thead><tr><th>항목</th><th>예</th></tr></thead><tbody><tr><td>플랫폼</td><td><strong>ComfyUI</strong>（또는 Custom ComfyUI）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:8188</code>（Desktop 흔히 <code>:8000</code>）</td></tr><tr><td>API Key</td><td>보통 비움</td></tr><tr><td>모델 / checkpoint</td><td>App이 가져온 목록; 기기에 파일 필요</td></tr></tbody></table><p>테스트 실패 시: 폰 브라우저로 같은 Base URL — 방화벽·미 listen 여부.</p><h2 id="클라우드-이미지-선택" tabindex="-1">클라우드 이미지（선택） <a class="header-anchor" href="#클라우드-이미지-선택" aria-label="Permalink to &quot;클라우드 이미지（선택）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>플랫폼</th><th>언제</th></tr></thead><tbody><tr><td>ChatGPT(OpenAI)</td><td>공식 Images API（대개 유료）</td></tr><tr><td>Gemini(Google)</td><td>Gemini 이미지（대부분 유료, Google 가격）</td></tr><tr><td>OpenRouter</td><td>이미지 지원 업스트림 라우트</td></tr><tr><td>Qwen</td><td>만상 / Qwen-Image（백련 무료 한도 확인）</td></tr><tr><td>Custom (OpenAI Images)</td><td>SiliconFlow, Agnes 등 <code>/images/generations</code> 호환（도생도도 generations, <code>/images/edits</code> 아님）</td></tr></tbody></table><p>무료 클라우드·Key: <a href="/ultra_guides/ko/free-cloud/#무료-이미지-생성">무료 클라우드 · 이미지</a>.</p><h2 id="채팅에서-이미지-생성" tabindex="-1">채팅에서 이미지 생성 <a class="header-anchor" href="#채팅에서-이미지-생성" aria-label="Permalink to &quot;채팅에서 이미지 생성&quot;">​</a></h2><p>기본 이미지 연결 후（주 채팅 모델도 필요 — 분석/프롬프트 변환）:</p><table tabindex="0"><thead><tr><th>입구</th><th>설명</th></tr></thead><tbody><tr><td><code>/imagine 프롬프트</code></td><td>자유 생성. 주 모델이 채팅 관련（「셀카」→ 대화+캐릭터 참고）인지 무관（「강아지」）인지 판단. 첨부 가능: 주 모델이 보고 프롬프트 작성, 생성 시 참고; 첨부 유무와 별도로 캐릭터/유저 그림 판정. 첨부는 생성 버블 소미리보기. 장수: <strong>이미지 설정 → 생성 수</strong>. 실패 시 버블 유지·재시도</td></tr><tr><td><code>/imagine scene</code> 또는 첨부 → 스토리</td><td>최근 대화로 현재 장면, 고정 1장</td></tr><tr><td><code>/imagine last</code> 또는 첨부 → 마지막 메시지</td><td>마지막 메시지, 고정 1장</td></tr><tr><td><code>/imagine background</code> 또는 첨부 → 배경</td><td>환경 배경, 고정 1장</td></tr><tr><td>말풍선 길게 누르기 → 이미지</td><td>해당 버블, 고정 1장</td></tr><tr><td>응답 이미지（스마트 / 키워드）</td><td>이미지 설정에서 「응답 이미지」켜고 트리거 선택. 일반 메시지（첨부 가능）후 대화 기준 바이패스 생성, 고정 1장; 첨부는 스타일 참고</td></tr></tbody></table><p>이미지 연결 없으면 첨부 네 모드·<code>/imagine</code> 시 「설정으로 / 취소」팝업（Toast·입력 비우기 없음）. 스마트/키워드 자동은 연결 없으면 Toast. 「응답 이미지」켤 때 연결 없으면 팝업, 스위치 유지 끔.</p><p>이미지만 있고 채팅 모델이 없으면 변환이 필요한 입구는 실패합니다.</p><h2 id="빠른-문제-해결" tabindex="-1">빠른 문제 해결 <a class="header-anchor" href="#빠른-문제-해결" aria-label="Permalink to &quot;빠른 문제 해결&quot;">​</a></h2><table tabindex="0"><thead><tr><th>현상</th><th>점검</th></tr></thead><tbody><tr><td>테스트 실패 / 타임아웃</td><td>PC 서비스 실행 중? <code>--api</code> / <code>--listen</code>? IP·포트? 같은 Wi‑Fi?</td></tr><tr><td>PC 브라우저 OK, 폰 안 됨</td><td>방화벽; 게스트 격리; <code>127.0.0.1</code> 입력</td></tr><tr><td>A1111 404</td><td><code>--api</code> 없음; Base URL에 경로 과다</td></tr><tr><td>Comfy 계속 로딩</td><td>PC Comfy 큐·오류; VRAM; checkpoint 없음</td></tr><tr><td>참고 있어도 얼굴 틀림（Comfy）</td><td>기본 workflow가 참고 미소비 → A1111 또는 클라우드</td></tr><tr><td><code>/imagine</code> 실패 버블 사라짐</td><td>실패는 원 버블+재시도; 중지만 미완료 자리 제거</td></tr></tbody></table><p>채팅 오류 코드: <a href="/ultra_guides/ko/manual/errors">오류</a>.</p>',24)])])}const g=e(r,[["render",n]]);export{m as __pageData,g as default};
